type OrganizationLifecyclePayload = TaskflowEventMap["organization.deleted"];

/**
 * Payloads already written by a listener during `emit`. The service records
 * the same object only when no listener ran, so each deletion or restoration
 * produces one audit row.
 */
const auditedLifecycle = new WeakSet<OrganizationLifecyclePayload>();

export async function auditOrganizationLifecycle(
  action: "organization.deleted" | "organization.restored",
  payload: OrganizationLifecyclePayload,
): Promise<void> {
  if (auditedLifecycle.has(payload)) return;
  auditedLifecycle.add(payload);

  try {
    const verb = action === "organization.deleted" ? "Deleted" : "Restored";
    await record(payload.orgId, action, {
      actorId: payload.actorId,
      subjectKind: "organization",
      subjectId: payload.orgId,
      projectId: null,
      summary: `${verb} workspace ${payload.slug}`,
    });
  } catch (error) {
    auditedLifecycle.delete(payload);
    throw error;
  }
}

