/**
 * Deletion is a soft delete guarded by a typed confirmation: the caller
 * retypes the slug. The workspace stays restorable until the retention
 * window closes, then the cleanup job purges it.
 */
export async function deleteOrganization(
  actor: Actor,
  input: DeleteOrganizationInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:delete", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  if (org.slug !== input.confirmSlug) {
    throw new Error("The confirmation does not match this organization's slug");
  }

  assertNotArchived("Organization", org.id, org);

  const archived = await orgRepo.archiveOrg(input.orgId);
  const payload = {
    ...envelope(archived.id, actor.userId),
    slug: archived.slug,
  };
  await emit("organization.deleted", payload);
  await auditOrganizationLifecycle("organization.deleted", payload);
  return archived;
}

/**
 * Brings a deleted workspace back during the retention window. No `Actor`
 * can be resolved for a deleted workspace, so the caller is a user id.
 * A workspace that is not deleted is returned unchanged.
 */
export async function restoreOrganization(
  userId: UserId,
  orgId: OrgId,
): Promise<Organization> {
  const org = await orgRepo.findOrgById(orgId);
  if (!org) throw new NotFoundError("Organization", orgId);

  if (
    org.archivedAt !== null &&
    new Date(org.archivedAt).getTime() <=
      deletedWorkspaceCutoff(new Date()).getTime()
  ) {
    throw new NotFoundError("Organization", orgId);
  }

  const member = await memberRepo.findMember(orgId, userId);
  if (!member) throw new NotFoundError("Organization", orgId);

  assertCan(
    { userId, orgId, role: member.role },
    "org:restore",
    orgResource(orgId),
  );

  if (org.archivedAt === null) return org;

  const restored = await orgRepo.restoreOrg(orgId);
  const payload = { ...envelope(restored.id, userId), slug: restored.slug };
  await emit("organization.restored", payload);
  await auditOrganizationLifecycle("organization.restored", payload);
  return restored;
}

